import cv2
cap = cv2.VideoCapture('/home/mageshkumar_sankar/videos/test.mp4')
if not cap.isOpened():
    raise FileNotFoundError('/home/mageshkumar_sankar/videos/test.mp4')
fps = cap.get(cv2.CAP_PROP_FPS) or 30.0
frame_index = 0
try:
    while True:
        ok, frame = cap.read()
        if not ok:
            break
        position_ms = cap.get(cv2.CAP_PROP_POS_MSEC)
        timestamp_s = position_ms / 1000.0 if position_ms > 0 else frame_index / fps
        metadata = {'frame_index': frame_index, 'timestamp_s': timestamp_s, 'fps': fps, 'width': frame.shape[1], 'height': frame.shape[0]}
        yield {'p01o': frame, 'p01m': metadata}
        frame_index += 1
finally:
    cap.release()

